import{_ as o,o as t,c as a,O as r}from"./chunks/framework.619bb88b.js";const n="/assets/DSCF2311.59fb6505.JPG",s="/assets/DSCF2313.58183a10.JPG",d="/assets/DSCF2317.cae880f5.JPG",i="/assets/DSCF2318.cfbeac34.JPG",c="/assets/DSCF2315.e07fbde4.JPG",h="/assets/DSCF2316.421834b0.JPG",l="/assets/DSCF2314.8938da09.JPG",p="/assets/DSCF2310.9d4536a7.JPG",b="/assets/DSCF2321.b0e2d8a6.JPG",m="/assets/DSCF2322.2124ddaf.JPG",u="/assets/DSCF2319.9debd26d.JPG",g="/assets/DSCF2323.66f81e52.JPG",f="/assets/DSCF2324.1f83e87a.JPG",L=JSON.parse('{"title":"How to assemble a V5 Pro LED hardware kit","description":"","frontmatter":{},"headers":[],"relativePath":"how_to_build/led_v5_setup.md","filePath":"how_to_build/led_v5_setup.md","lastUpdated":1788722140000}'),k={name:"how_to_build/led_v5_setup.md"};function w(y,e,E,V,D,_){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-assemble-a-v5-pro-led-hardware-kit" tabindex="-1">How to assemble a V5 Pro LED hardware kit <a class="header-anchor" href="#how-to-assemble-a-v5-pro-led-hardware-kit" aria-label="Permalink to &quot;How to assemble a V5 Pro LED hardware kit&quot;">​</a></h1><p>This guide covers the V5 Pro LED Dev kit. The kit uses one USB-C mainboard, six standard <code>V5</code> LED boards, two <code>V5E</code> end boards, and various two-wire cables.</p><p><a href="https://store.eyetrackvr.dev/products/v5-pro-led-dev-kit-1" target="_blank" rel="noreferrer">Buy the V5 Pro LED Dev Kit from the EyeTrackVR Store</a>.</p><p><a href="https://github.com/EyeTrackVR/EyeTrackVR-Hardware/tree/main/IR%20Emmitter/V5%20Pro" target="_blank" rel="noreferrer">View the V5 Pro PCB source files on GitHub</a>.</p><div class="warning custom-block"><p class="custom-block-title">Disconnect power first</p><p>Do all wiring with the USB-C cable disconnected. Recheck every connector before applying power.</p></div><h2 id="identify-the-parts" tabindex="-1">Identify the parts <a class="header-anchor" href="#identify-the-parts" aria-label="Permalink to &quot;Identify the parts&quot;">​</a></h2><h3 id="mainboard" tabindex="-1">Mainboard <a class="header-anchor" href="#mainboard" aria-label="Permalink to &quot;Mainboard&quot;">​</a></h3><p>The V5 mainboard has two LED outputs. With the component side facing you and the USB-C port at the bottom, the sockets are marked <code>R</code> for the right eye and <code>L</code> for the left eye.</p><p><img src="'+n+'" alt="Component side of the V5 mainboard, showing the R and L output labels"></p><p>The back is labeled <code>Right LED</code> and <code>Left LED</code>. Use these labels to choose the correct socket. Do not rely on where a socket appears in a rotated photo.</p><p><img src="'+s+'" alt="Reverse side of the V5 mainboard, showing the Right LED and Left LED labels"></p><h3 id="led-boards" tabindex="-1">LED boards <a class="header-anchor" href="#led-boards" aria-label="Permalink to &quot;LED boards&quot;">​</a></h3><p>Each eye uses three standard <code>V5</code> boards and one <code>V5E</code> end board. The two types are very similar, so identify them by the marking on the <strong>LED side</strong> of the board as well as color difference (E is Purple).</p><h4 id="standard-v5-board-three-per-eye" tabindex="-1">Standard <code>V5</code> board (three per eye) <a class="header-anchor" href="#standard-v5-board-three-per-eye" aria-label="Permalink to &quot;Standard `V5` board (three per eye)&quot;">​</a></h4><p>A standard board is marked <code>V5</code>. These are the first three boards in each eye&#39;s strand. Each one connects to the next board.</p><p><strong>LED side: the <code>V5</code> marking is visible.</strong></p><p><img src="'+d+'" alt="LED side of a standard board marked V5"></p><p><strong>Connector side of the same standard <code>V5</code> board:</strong></p><p><img src="'+i+'" alt="Connector side of a standard V5 board"></p><h4 id="end-v5e-board-one-per-eye" tabindex="-1">End <code>V5E</code> board (one per eye) <a class="header-anchor" href="#end-v5e-board-one-per-eye" aria-label="Permalink to &quot;End `V5E` board (one per eye)&quot;">​</a></h4><p>An end board is marked <code>V5E</code>. It must be the fourth and final board in the strand, farthest from the mainboard.</p><p><strong>LED side: look for the extra <code>E</code> in the <code>V5E</code> marking.</strong></p><p><img src="'+c+'" alt="LED side of an end board marked V5E"></p><p><strong>Connector side of the same <code>V5E</code> end board:</strong></p><p><img src="'+h+'" alt="Connector side of a V5E end board"></p><div class="tip custom-block"><p class="custom-block-title">The reliable identification check</p><p>The connector sides look similar. If you are unsure which board you have, turn it over and read <code>V5</code> or <code>V5E</code> next to the LED.</p></div><p>The complete kit contains six <code>V5</code> boards and two <code>V5E</code> boards. Check the printed markings and board color.</p><p><img src="'+l+'" alt="Six standard V5 boards and two V5E end boards"></p><h3 id="cables-and-keyed-connectors" tabindex="-1">Cables and keyed connectors <a class="header-anchor" href="#cables-and-keyed-connectors" aria-label="Permalink to &quot;Cables and keyed connectors&quot;">​</a></h3><p>Here are 6 &quot;Short&quot; wires typically used between LED and LED.</p><p><img src="'+p+'" alt="The different two-wire cables supplied with the V5 kit"></p><div class="tip custom-block"><p class="custom-block-title">The connectors are keyed</p><p>The two-pin connectors are keyed and normally cannot be inserted backward. If a plug does not go in easily, stop and check its direction. Never force it into the socket, although they may take some force to plug in. Double check if unsure.</p></div><div class="tip custom-block"><p class="custom-block-title">Unplug cables by pulling. Do not use tools</p><p>To disconnect a cable, pull both wires together and straight out from the connector. This is safe, and the cables are designed for it. Do not pry at the plug with pliers, tweezers, a screwdriver, or other tools. Tools can damage the small connector. Before pulling, remove any glue or anything else that would stop the plug from coming out normally.</p></div><h2 id="assemble-the-two-eye-strands" tabindex="-1">Assemble the two eye strands <a class="header-anchor" href="#assemble-the-two-eye-strands" aria-label="Permalink to &quot;Assemble the two eye strands&quot;">​</a></h2><p>Build the left and right strands separately. The order for <strong>each</strong> eye is:</p><p><code>mainboard output -&gt; V5 -&gt; V5 -&gt; V5 -&gt; V5E</code></p><p>This means the completed dual-eye kit has two four-board strands:</p><table><thead><tr><th>Eye</th><th>Mainboard socket</th><th>Board order</th></tr></thead><tbody><tr><td>Right</td><td><code>R</code> / <code>Right LED</code></td><td><code>V5 -&gt; V5 -&gt; V5 -&gt; V5E</code></td></tr><tr><td>Left</td><td><code>L</code> / <code>Left LED</code></td><td><code>V5 -&gt; V5 -&gt; V5 -&gt; V5E</code></td></tr></tbody></table><p>Use the following completed assemblies as wiring references. They show the <strong>two correct configurations</strong> for the V5 kit. The board orientation and cable routing differ slightly, but both use three <code>V5</code> boards followed by one <code>V5E</code> board for each eye.</p><p>Note the LED board orientation in how they are plugged in. Be careful as a wrong orientation will cause it to not work.</p><p><strong>Correct assembly example 1:</strong></p><p><img src="'+b+'" alt="First correct full V5 dual-eye assembly"></p><p><strong>Correct assembly example 2:</strong></p><p><img src="'+m+'" alt="Full V5 dual-eye layout with three V5 boards followed by one V5E board in each strand"></p><p>If your headset mount needs more distance at the end of a strand, you may use a longer cable between the third <code>V5</code> board and the final <code>V5E</code> board.</p><h3 id="_1-connect-the-mainboard-ends" tabindex="-1">1. Connect the mainboard ends <a class="header-anchor" href="#_1-connect-the-mainboard-ends" aria-label="Permalink to &quot;1. Connect the mainboard ends&quot;">​</a></h3><p>Connect one long strand cable to <code>R</code> and the other to <code>L</code>. In the photo below, one cable is connected to the <code>R</code> socket.</p><p><img src="'+u+'" alt="A two-wire cable connected to the R output of the V5 mainboard"></p><h3 id="_2-add-three-standard-boards-to-each-strand" tabindex="-1">2. Add three standard boards to each strand <a class="header-anchor" href="#_2-add-three-standard-boards-to-each-strand" aria-label="Permalink to &quot;2. Add three standard boards to each strand&quot;">​</a></h3><p>Starting from each mainboard cable, connect three boards marked <code>V5</code>. Connect the mainboard cable to the first board, then connect the first board to the second and the second board to the third. Following the oreintation shown in the working setup examples above.</p><p>Before plugging in each connector, check these three things:</p><ol><li>The board is marked <code>V5</code>, not <code>V5E</code>.</li><li>All three boards face the same direction and match the chosen assembly photo.</li><li>The plug is straight and lines up with the socket. No pins are bent or sticking out.</li></ol><h3 id="_3-finish-each-strand-with-a-v5e-board" tabindex="-1">3. Finish each strand with a V5E board <a class="header-anchor" href="#_3-finish-each-strand-with-a-v5e-board" aria-label="Permalink to &quot;3. Finish each strand with a V5E board&quot;">​</a></h3><p>Connect one board marked <code>V5E</code> after the third standard board in each strand. The <code>V5E</code> board is last, so nothing connects after it.</p><p>Check the orinetation to be correct compared to the exampels above.</p><h2 id="final-check-and-power-up" tabindex="-1">Final check and power-up <a class="header-anchor" href="#final-check-and-power-up" aria-label="Permalink to &quot;Final check and power-up&quot;">​</a></h2><p>Before connecting USB-C, check both strands from the mainboard outward:</p><ul><li><code>R</code> feeds exactly three <code>V5</code> boards and then one <code>V5E</code> board.</li><li><code>L</code> feeds exactly three <code>V5</code> boards and then one <code>V5E</code> board.</li><li>Every plug is pushed in all the way.</li><li>No exposed metal can touch the headset or another board.</li></ul><p>The mainboard can then be installed in its printed housing. Keep both LED cables clear of the case edges so they are not pinched when the housing is slid on.</p><p>Insert the PCB and slide it into the 3d print. Note this may take some force, be careful but its okay to push it!</p><p><img src="'+g+'" alt="V5 mainboard in its housing with both LED cables connected"></p><p><img src="'+f+'" alt="Closed V5 mainboard housing with both LED cables exiting without being pinched"></p><p>Connect USB-C only after completing the inspection above.</p><h3 id="optional-sweat-protection" tabindex="-1">Optional sweat protection <a class="header-anchor" href="#optional-sweat-protection" aria-label="Permalink to &quot;Optional sweat protection&quot;">​</a></h3><p>Most people do not need additional sweat protection. If you sweat heavily, you can apply a thin layer of clear nail polish to the board <strong>around the LED and exposed pads, but not on top of the LED lens</strong>.</p><p>Before applying it:</p><ol><li>Assemble and test the entire kit until it works correctly.</li><li>Disconnect USB-C and all power.</li><li>Keep nail polish out of the wire connectors and away from connector contacts.</li><li>Let the nail polish dry completely before reconnecting power.</li></ol><div class="danger custom-block"><p class="custom-block-title">Do not use superglue</p><p>Do not use superglue on or around the LED boards. Superglue can damage the LEDs permanantly.</p></div><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="help-no-leds-light-up" tabindex="-1">Help! No LEDs light up <a class="header-anchor" href="#help-no-leds-light-up" aria-label="Permalink to &quot;Help! No LEDs light up&quot;">​</a></h3><p>Infrared light is invisible to the human eye. Check the LEDs through a phone camera or an ESP camera to confirm whether they are on.</p><p>If no LEDs appear through the camera:</p><ol><li>Ensure every connection matches one of the two example eye strands shown above.</li><li>Check that every connector lines up correctly and is pushed in all the way.</li><li>Restart the mainboard by unplugging its power cable and plugging it back in.</li><li>Confirm that the orange LED on the mainboard is on.</li></ol><h3 id="the-mainboard-has-no-orange-led" tabindex="-1">The mainboard has no orange LED <a class="header-anchor" href="#the-mainboard-has-no-orange-led" aria-label="Permalink to &quot;The mainboard has no orange LED&quot;">​</a></h3><p>Try a different power source, such as a computer, battery bank, or USB wall adapter. Also inspect the mainboard and LED boards for physical damage.</p><h3 id="help-i-m-missing-a-part-or-it-isn-t-working" tabindex="-1">Help! I&#39;m missing a part or it isn&#39;t working <a class="header-anchor" href="#help-i-m-missing-a-part-or-it-isn-t-working" aria-label="Permalink to &quot;Help! I&#39;m missing a part or it isn&#39;t working&quot;">​</a></h3><p>If an important part is missing or the kit still does not work after completing the checks above, email <a href="mailto:support@fovea-labs.com" target="_blank" rel="noreferrer">support@fovea-labs.com</a>. We will do our best to make it right.</p>',77)])])}const P=o(k,[["render",w]]);export{L as __pageData,P as default};
